body.script:
//
(function(){
  var KEY='keg-theme', root=document.documentElement;
  try{ var s=localStorage.getItem(KEY); if(s){ root.setAttribute('data-theme',s); } }catch(e){}
  function cur(){ var a=root.getAttribute('data-theme'); return a?a:(window.matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'); }
  function toggle(){ var n=cur()==='dark'?'light':'dark'; root.setAttribute('data-theme',n); try{localStorage.setItem(KEY,n);}catch(e){} }
  var t=document.getElementById('themeToggle');
  if(t){ t.addEventListener('click',toggle); t.addEventListener('keydown',function(e){ if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();} }); }
  var h=document.getElementById('hamburger');
  if(h){ h.addEventListener('click',function(){ var n=document.getElementById('nav'); if(n){ n.style.display=(n.style.display==='flex')?'none':'flex'; } }); }
  var grid=document.getElementById('latestGrid');
  if(grid && grid.children.length===0 && /^\/($|\?)/.test(location.pathname + location.search)){
    fetch('/feeds/posts/default?alt=json&max-results=9').then(function(r){return r.json();}).then(function(feed){
      var posts=((feed.feed||{}).entry||[]).slice(1,9);
      posts.forEach(function(post){
        var title=((post.title||{}).$t)||'Korea guide';
        var url=((post.link||[]).filter(function(l){return l.rel==='alternate';})[0]||{}).href||'#';
        var label=((post.category||[])[0]||{}).term||'Guide';
        var date=new Date(((post.published||{}).$t)||Date.now()).toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric'});
        var html=((post.content||post.summary||{}).$t)||'';
        var img='';
        var media=(post.media$thumbnail||{}).url;
        var match=html.match(/<img[^>]+src=["']([^"']+)["']/i);
        if(media){ img=media.replace(/\/s72-c\//,'/s640/'); }
        if(!img && match){ img=match[1]; }
        var plain=html.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,135);
        var card=document.createElement('article');
        card.className='card';
        card.innerHTML='<a href="'+url+'"><div class="thumb">'+(img?'<img loading="lazy" src="'+img.replace(/"/g,'&quot;')+'" alt="">':'')+'<span class="tag">'+label+'</span></div><div class="card-b"><div class="card-t">'+title+'</div><div class="card-x">'+plain+'</div><div class="card-m">'+date+'</div></div></a>';
        grid.appendChild(card);
      });
    }).catch(function(){});
  }
})();
//
